<?php

namespace App\Filament\Resources\SeoPeriodicReports;

use App\Filament\Resources\SeoPeriodicReports\Pages\ManageSeoPeriodicReports;
use App\Filament\Resources\SeoPeriodicReports\Tables\SeoPeriodicReportsTable;
use App\Models\SeoPeriodicReport;
use BackedEnum;
use Filament\Resources\Resource;
use Filament\Schemas\Schema;
use Filament\Support\Icons\Heroicon;
use Filament\Tables\Table;

/**
 * System-generated by App\Domain\Seo\PeriodicReportService (monthly, or
 * on demand via the "تولید گزارش" header action) - no create/edit form,
 * only a "مشاهده / چاپ" link to the stored, print-ready HTML.
 */
class SeoPeriodicReportResource extends Resource
{
    protected static ?string $model = SeoPeriodicReport::class;

    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedDocumentChartBar;

    protected static string|\UnitEnum|null $navigationGroup = 'مرکز سئو';

    protected static ?string $navigationLabel = 'گزارش دوره‌ای مدیریتی';

    protected static ?string $modelLabel = 'گزارش دوره‌ای';

    protected static ?string $pluralModelLabel = 'گزارش‌های دوره‌ای';

    public static function form(Schema $schema): Schema
    {
        return $schema->components([]);
    }

    public static function table(Table $table): Table
    {
        return SeoPeriodicReportsTable::configure($table);
    }

    public static function getPages(): array
    {
        return [
            'index' => ManageSeoPeriodicReports::route('/'),
        ];
    }
}
